 1→#!/usr/bin/env node
 2→/**
 3→ * Set the identity used by the Nalar bridge.
 4→ *
 5→ * This is the host-side counterpart of SSO: the WorkBuddy agent never learns
 6→ * or changes the identity itself, it only reads the file written here.
 7→ *
 8→ * Usage: node scripts/set-identity.mjs <id>
 9→ *        node scripts/set-identity.mjs --show
10→ */
11→
12→import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
13→import { homedir } from "node:os";
14→import { dirname, join, resolve } from "node:path";
15→
16→const identityFile = resolve(
17→  String(process.env.NALAR_IDENTITY_FILE ?? join(homedir(), ".nalar", "identity"))
18→);
19→
20→const [command] = process.argv.slice(2);
21→
22→if (!command || command === "--help" || command === "-h") {
23→  console.log(
24→    [
25→      "Pemakaian: node scripts/set-identity.mjs <id>",
26→      "        node scripts/set-identity.mjs --show",
27→      "",
28→      `File identitas: ${identityFile}`
29→    ].join("\n")
30→  );
31→  process.exit(command ? 0 : 2);
32→}
33→
34→if (command === "--show") {
35→  const current = existsSync(identityFile)
36→    ? readFileSync(identityFile, "utf8").split(/\r?\n/)[0]?.trim()
37→    : "";
38→  console.log(
39→    current
40→      ? `Identitas aktif: ${current} (${identityFile})`
41→      : `Belum ada identitas. Jalankan: node scripts/set-identity.mjs <id>`
42→  );
43→  process.exit(0);
44→}
45→
46→if (!/^[a-z0-9_-]{1,64}$/i.test(command)) {
47→  console.error("ID identitas tidak valid (huruf, angka, - dan _ saja).");
48→  process.exit(2);
49→}
50→
51→mkdirSync(dirname(identityFile), { recursive: true });
52→writeFileSync(identityFile, `${command}\n`, "utf8");
53→console.log(`Identitas host disetel: ${command} -> ${identityFile}`);
54→
